import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative normalized distance between a machine's load after taking the job and the current maximum load."""
    l = np.asarray(loads, dtype=float)
    if l.size == 0:
        return np.zeros(0, dtype=float)
    j = float(job)
    m = float(np.max(l))
    scale = max(m, abs(j), 1e-9)
    return -np.abs(l + j - m) / scale
